// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 firstAmount, uint256 secondAmount, address actor) public {
        vm.assume(actor != address(0));
        bound(secondAmount, 1, type(uint256).max);
        // widen the domain: force the pair (firstAmount, secondAmount) to be an overflowing sum
        // so the guard in P is exactly what blocks the deposit.
        vm.assume(firstAmount > type(uint256).max - secondAmount);

        vm.deal(actor, type(uint256).max);

        vm.prank(actor);
        c.addToBalance{value: firstAmount}();
        uint256 before = c.getBalance(actor);

        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: secondAmount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever a deposit succeeds, the actor's balance must not decrease
        // (successful deposits are monotone). P always satisfies this; M wraps and violates it.
        assertTrue(!ok || c.getBalance(actor) >= before);
    }
}

