pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        // wide domain: both amounts span the full uint256 range, actor arbitrary

        // first deposit: sets a fuzzed starting balance (always succeeds from zero balance)
        vm.deal(actor, amount1);
        vm.prank(actor);
        c.addToBalance{value: amount1}();
        uint256 bal1 = c.getBalance(actor);

        // second deposit: triggers wrap-around when bal1 + amount2 >= 2^256
        vm.deal(actor, amount2);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount2}() { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 bal2 = c.getBalance(actor);
            // RULE: a successful deposit leaves the caller's balance at least the
            // deposited amount (balances never wrap). The reference reverts the
            // overflowing deposit (ok == false); the mutant succeeds and wraps.
            assertTrue(bal2 >= amount2);
        }
    }
}

