pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amountA, uint256 amountB, address actorA, address actorB) public {
        // keep the domain wide: only require distinct actors and nonzero amounts
        vm.assume(actorA != address(0));
        vm.assume(actorB != address(0));
        vm.assume(actorA != actorB);
        vm.assume(amountA > 0);
        vm.assume(amountB > 0);

        // fund each depositor so the payable calls are admissible
        vm.deal(actorA, amountA);
        vm.prank(actorA);
        c.addToBalance{value: amountA}();

        vm.deal(actorB, amountB);
        vm.prank(actorB);
        c.addToBalance{value: amountB}();

        // general rule: the ledger is additive and consistent with the contract's ether
        assertTrue(
            c.getBalance(actorA) == amountA &&
            c.getBalance(actorB) == amountB &&
            address(c).balance == amountA + amountB
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 firstDeposit, uint256 hugeDeposit, address actor) public {
        // Admissible domain: actor is a usable address, first deposit is a normal positive amount,
        // and hugeDeposit is exactly in the range that overflows actor's balance after the first deposit.
        vm.assume(actor != address(0) && actor != address(c));
        firstDeposit = bound(firstDeposit, 1, 2**128);
        vm.assume(hugeDeposit > type(uint256).max - firstDeposit);

        // Fund the actor so it can send both amounts.
        vm.deal(actor, firstDeposit + hugeDeposit);

        vm.startPrank(actor);
        // Establish a nonzero balance; this succeeds on both versions.
        c.addToBalance{value: firstDeposit}();

        // Now deposit an amount that overflows the recorded balance.
        // Reference C: the require guard (balance + value >= balance) overflows -> revert.
        // Mutant M: unchecked balance update wraps -> succeeds.
        bool ok;
        try c.addToBalance{value: hugeDeposit}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // General rule: any deposit that would overflow the caller's balance is rejected.
        assertTrue(!ok, "overflowing deposit must be rejected");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test() public payable {
        require(address(this).balance >= 1 wei);
        uint before = c.getBalance(address(this));
        c.addToBalance{value: 1 wei}();
        assert(c.getBalance(address(this)) == before + 1 wei);
    }
    receive() external payable {}
}

