contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function test(uint amount) public {
        require(address(this).balance >= amount && address(this).balance >= 2 * amount);
        c.addToBalance{value: amount}();
        uint b1 = c.getBalance(address(this));
        c.withdrawBalance();
        uint b2 = c.getBalance(address(this));
        assert(b1 == amount && b2 == 0 && address(this).balance == 3 * amount - amount);
    }
